import{_ as e,o,c as d,ag as a}from"./chunks/framework.B7PviQjB.js";const m=JSON.parse('{"title":"Import and export files","description":"Which file formats each Wafflebase editor imports and exports, what each conversion keeps, and the size limits.","frontmatter":{"title":"Import and export files","description":"Which file formats each Wafflebase editor imports and exports, what each conversion keeps, and the size limits.","type":"reference"},"headers":[],"relativePath":"files/import-export.md","filePath":"files/import-export.md"}'),r={name:"files/import-export.md"};function s(i,t,n,l,c,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="import-and-export-files" tabindex="-1">Import and export files <a class="header-anchor" href="#import-and-export-files" aria-label="Permalink to &quot;Import and export files&quot;">​</a></h1><p>This page lists the file formats each editor can bring in and take out, what each conversion keeps, and the limits that apply.</p><p>Importing always creates a new document; it never changes an open one. To import, <a href="/docs/files/upload.html">upload the file</a>. Exporting downloads a file and leaves the document unchanged.</p><h2 id="formats-at-a-glance" tabindex="-1">Formats at a glance <a class="header-anchor" href="#formats-at-a-glance" aria-label="Permalink to &quot;Formats at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Editor</th><th>Import</th><th>Export in the app</th></tr></thead><tbody><tr><td><a href="/docs/sheets/">Sheets</a></td><td>Excel (<code>.xlsx</code>), CSV (<code>.csv</code>), TSV (<code>.tsv</code>), JSON (<code>.json</code>, <code>.jsonl</code>, <code>.ndjson</code>), Parquet (<code>.parquet</code>)</td><td>None. Use the <a href="/docs/developers/cli/sheets.html">CLI</a> for CSV or JSON.</td></tr><tr><td><a href="/docs/docs-editor/">Docs</a></td><td>Word (<code>.docx</code>)</td><td>Word (<code>.docx</code>), PDF (<code>.pdf</code>), Markdown (<code>.md</code>), plain text (<code>.txt</code>)</td></tr><tr><td><a href="/docs/slides/">Slides</a></td><td>PowerPoint (<code>.pptx</code>)</td><td>PowerPoint (<code>.pptx</code>), PDF (<code>.pdf</code>)</td></tr><tr><td><a href="/docs/notes/">Notes</a></td><td>None. Use the <a href="/docs/developers/cli/documents.html#notes">CLI</a> for Markdown.</td><td>None. Use the <a href="/docs/developers/cli/documents.html#notes">CLI</a> for Markdown.</td></tr><tr><td><a href="/docs/board/">Board</a></td><td>A Miro board, with <strong>New &gt; Import from Miro…</strong></td><td>PNG, PDF (whole board or selection)</td></tr><tr><td><a href="/docs/files/pdfs.html">PDF</a></td><td><code>.pdf</code>, stored as-is</td><td>Download the original</td></tr><tr><td><a href="/docs/files/images.html">Image</a></td><td><code>.png</code>, <code>.jpg</code>, <code>.jpeg</code>, <code>.gif</code>, <code>.webp</code>, stored as-is</td><td>Download the original</td></tr><tr><td>Other files</td><td>Any other extension, stored as-is</td><td>Download the original</td></tr></tbody></table><p>A Markdown (<code>.md</code>) upload is stored as a file. It does not become a note.</p><h2 id="where-to-export" tabindex="-1">Where to export <a class="header-anchor" href="#where-to-export" aria-label="Permalink to &quot;Where to export&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>How to export</th></tr></thead><tbody><tr><td>Doc</td><td>Click the download icon (<strong>Export</strong>) in the header, then choose a format.</td></tr><tr><td>Presentation</td><td>Click the download icon (<strong>Export</strong>) in the header, then choose a format. It is unavailable while the deck has no slides.</td></tr><tr><td>Board</td><td>Click the download icon (<strong>Download</strong>) in the top-right corner of the canvas.</td></tr><tr><td>PDF, image, or other file</td><td>Click the download icon in the header (<strong>Download PDF</strong>, <strong>Download image</strong>, or <strong>Download file</strong>).</td></tr></tbody></table><p>On a phone, a doc or presentation lists its formats under <strong>Export</strong> in the ⋮ menu (<strong>More</strong>) in the header. The board&#39;s <strong>Download</strong> button stays on the canvas.</p><p>Docs and presentations export from the editor in your workspace, not from a share link. Anyone who can open a board, including a viewer, can download it.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th></tr></thead><tbody><tr><td>Any uploaded file</td><td>100 MB</td></tr><tr><td>Image file (including types stored as plain files, such as HEIC)</td><td>25 MB</td></tr><tr><td>Each image inside an imported <code>.docx</code> or <code>.pptx</code></td><td>10 MB</td></tr><tr><td>CSV or TSV import</td><td>40,000 cells, plus an overall size limit</td></tr><tr><td>Parquet import</td><td>40,000 cells</td></tr><tr><td>Excel or JSON import</td><td>No cell limit</td></tr></tbody></table><p>A CSV or TSV file over its limit is cut short rather than rejected. The sheet keeps the rows that fit, and the upload shows <code>Only the first N rows were imported.</code> If even the first row is too large, the upload fails with a message such as <code>This file has too many columns to import</code>.</p><p>A Parquet file over 40,000 cells is rejected before anything is imported.</p><h2 id="what-import-keeps" tabindex="-1">What import keeps <a class="header-anchor" href="#what-import-keeps" aria-label="Permalink to &quot;What import keeps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Kept</th></tr></thead><tbody><tr><td><code>.xlsx</code></td><td>Every worksheet as a tab, with values, formulas, merged cells, column widths, row heights, hidden rows and columns, and cell formatting: fill, borders, bold, italic, underline, strikethrough, text color, alignment, and number format</td></tr><tr><td><code>.csv</code>, <code>.tsv</code></td><td>The values, in one tab named after the file. A <code>.csv</code> can use a comma, semicolon, tab, or pipe between values; the separator is detected for you.</td></tr><tr><td><code>.json</code>, <code>.jsonl</code>, <code>.ndjson</code></td><td>One row per object, with the keys as a bold header row. A file can hold one object, an array of objects, or one object per line.</td></tr><tr><td><code>.parquet</code></td><td>The rows, in one tab, with the column names as a bold header row</td></tr><tr><td><code>.docx</code></td><td>Paragraphs, headings, lists, tables, images, inline formatting, headers and footers, and page size and margins</td></tr><tr><td><code>.pptx</code></td><td>Slides, text boxes, shapes, images, tables, charts, groups, theme colors, transitions, and animations</td></tr></tbody></table><p>When a <code>.pptx</code> needs fallbacks, the upload shows a warning that counts them, for example <code>Imported with 2 image(s) skipped.</code> Charts that can&#39;t be read appear as placeholders.</p><p>Excel font family, font size, hyperlinks, and conditional formatting are not imported.</p><h2 id="what-export-keeps" tabindex="-1">What export keeps <a class="header-anchor" href="#what-export-keeps" aria-label="Permalink to &quot;What export keeps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Kept</th></tr></thead><tbody><tr><td>Word (<code>.docx</code>)</td><td>The full document, including tables, headers, and footers</td></tr><tr><td>Doc PDF (<code>.pdf</code>)</td><td>Paginated pages that match the page layout on screen</td></tr><tr><td>Markdown (<code>.md</code>)</td><td>Headings, lists, tables, links, images, bold, italic, and strikethrough</td></tr><tr><td>Plain text (<code>.txt</code>)</td><td>Text only, one paragraph per line, with table cells separated by tabs and images shown as <code>[image]</code></td></tr><tr><td>PowerPoint (<code>.pptx</code>)</td><td>An editable deck with slides, shapes, text, images, tables, and the theme</td></tr><tr><td>Slides PDF (<code>.pdf</code>)</td><td>One slide per page</td></tr><tr><td>Board PNG or PDF</td><td>The whole board, or only the selected items</td></tr></tbody></table><p>Markdown export drops alignment, indents, line spacing, color, font and size, underline, superscript and subscript, merged and nested table cells, and headers and footers. A link that is not an ordinary web address is dropped, and its text stays. An image that is neither a web address nor embedded image data becomes the text <code>[image]</code>.</p><h2 id="fidelity-notes" tabindex="-1">Fidelity notes <a class="header-anchor" href="#fidelity-notes" aria-label="Permalink to &quot;Fidelity notes&quot;">​</a></h2><ul><li><code>.docx</code> and <code>.pptx</code> import is best effort. Rare features, such as embedded objects, macros, audio, and video, may be simplified or dropped.</li><li>If an imported file uses a font that Wafflebase doesn&#39;t have, a close substitute is shown.</li><li>Exporting a file you imported keeps its structure and content, but the file is not identical to the original.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/files/upload.html">Upload files</a> to import a file.</li><li><a href="/docs/board/export-and-import.html">Board export and import</a> to download a board or bring one in from Miro.</li><li><a href="/docs/developers/cli/documents.html#notes">Documents and notes on the CLI</a> to import and export notes as Markdown.</li><li><a href="/docs/developers/cli/sheets.html">Sheets on the CLI</a> to export a tab as CSV or JSON.</li></ul>',25)])])}const f=e(r,[["render",s]]);export{m as __pageData,f as default};
